def combination_sum_bottom_up(nums: Any, target: Any) -> object {
    combs = [0] * (target + 1);
    combs[0] = 1;
    for i in range(0, len(combs)) {
        for num in nums {
            if ((i - num) >= 0) {
                combs[i] += combs[(i - num)];
            }
        }
    }
    return combs[target];
}

